CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 NUMERIC UNIQUE, c1 INTEGER CHECK(c1 IS NULL OR length(c1) < 40), c2 TEXT);
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES('gamma', -63, x'cd');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL, c1 REAL DEFAULT 'd', c2 INTEGER CHECK(c2 IS NULL OR length(c2) < 40), c3 INT, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(2.5, 1, 253, x'4dfbce', 8);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(186, -698.9388, 353, 5, NULL);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 TEXT, c1  CHECK(c1 IS NULL OR length(c1) < 40), c2 REAL UNIQUE, ref INTEGER REFERENCES t1(id));
INSERT OR IGNORE INTO t2(c0, c1, c2, ref) VALUES(-0.0, NULL, x'db', 3);
SELECT length('naïve'), upper('naïve'), lower('naïve'), substr('naïve', 3, 5), instr('naïve', 'iota'), replace('naïve', 'a', '_'), trim('naïve'), ltrim('naïve', 'ab'), hex('naïve'), quote('naïve'), unicode('naïve'), 'naïve' LIKE '%', 'naïve' GLOB '*', char(65, 678), 'naïve' || 'iota', 'naïve' < 'iota', 'naïve' = 'iota' COLLATE NOCASE;
SELECT length('NULL'), upper('NULL'), lower('NULL'), substr('NULL', 4, 4), instr('NULL', 'alpha'), replace('NULL', 'é', ''), trim('NULL'), ltrim('NULL', 'ab'), hex('NULL'), quote('NULL'), unicode('NULL'), 'NULL' LIKE '%', 'NULL' GLOB 'a*', char(75, 638), 'NULL' || 'alpha', 'NULL' < 'alpha', 'NULL' = 'alpha' COLLATE NOCASE;
SELECT length('café'), upper('café'), lower('café'), substr('café', -1, 3), instr('café', 'MU'), replace('café', 'a', 'XY'), trim('café'), ltrim('café', 'ab'), hex('café'), quote('café'), unicode('café'), 'café' LIKE '%a_', 'café' GLOB '?', char(65, 915), 'café' || 'MU', 'café' < 'MU', 'café' = 'MU' COLLATE NOCASE;
SELECT length('iota'), upper('iota'), lower('iota'), substr('iota', -1, 4), instr('iota', 'beta'), replace('iota', '', '_'), trim('iota'), ltrim('iota', 'ab'), hex('iota'), quote('iota'), unicode('iota'), 'iota' LIKE '%', 'iota' GLOB 'a*', char(79, 901), 'iota' || 'beta', 'iota' < 'beta', 'iota' = 'beta' COLLATE NOCASE;
SELECT length('señor'), upper('señor'), lower('señor'), substr('señor', 4, 2), instr('señor', 'café'), replace('señor', '', ''), trim('señor'), ltrim('señor', 'ab'), hex('señor'), quote('señor'), unicode('señor'), 'señor' LIKE 'a%', 'señor' GLOB '?', char(84, 419), 'señor' || 'café', 'señor' < 'café', 'señor' = 'café' COLLATE NOCASE;
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', -3, 4), instr('it''s', 'naïve'), replace('it''s', 'e', '_'), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE 'a%', 'it''s' GLOB '?', char(75, 737), 'it''s' || 'naïve', 'it''s' < 'naïve', 'it''s' = 'naïve' COLLATE NOCASE;
SELECT json_valid('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}'), json('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}'), json_type('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}'), json_array_length('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}'), json_extract('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}', '$.a', '$[1]', '$.b[2].c'), '{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}' -> '$.b', '{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}' ->> '$.n.m.o';
SELECT key, value, type FROM json_each('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}') ORDER BY key;
SELECT json_set('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}', '$.z', 1), json_insert('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}', '$.a', 2), json_remove('{"name":"café","tags":["a","b"],"n":{"m":{"o":-1}}}', '$.a'), json_patch('{"a":1}', '{"b":2}');
SELECT json_group_array(id), json_group_object(CAST(id AS TEXT), c1) FROM t0;
SELECT json_object('id', id, 'v', c2) FROM t0 ORDER BY id LIMIT 4;
